export class CARDIODictionaryUtils {
  static findByCode(code: string): MedicalCodeEntry | undefined {
    return CARDIO_ICD10_DATABASE.find(item => item.code.toLowerCase() === code.toLowerCase());
  }

  static searchByDescription(query: string): MedicalCodeEntry[] {
    const q = query.toLowerCase();
    return CARDIO_ICD10_DATABASE.filter(item => item.description.toLowerCase().includes(q));
  }
}
